// Same shape as the module generated by openapi-generator (typescript-angular).
// `ModuleWithProviders` is a type-only export of @angular/core and is only used
// in a type position, so the import must be elided from the emitted JS.
import { ModuleWithProviders, NgModule } from '@angular/core';
import { Configuration } from './configuration';

@NgModule({})
export class ApiModule {
  public static forRoot(
    configurationFactory: () => Configuration,
  ): ModuleWithProviders<ApiModule> {
    return {
      ngModule: ApiModule,
      providers: [{ provide: Configuration, useFactory: configurationFactory }],
    };
  }
}
